dashboard.definition:
{
	"dataSources": {
		"ds_Sdym09Wi": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"if-stats.in_octets\") as in_octets latest(\"if-stats.speed\") as speed WHERE index=\"cisco_metrics\" node=* interface=* span=60s by node interface\n| streamstats current=f latest(_time) as prev_time_ms by node interface\n| streamstats current=f latest(in_octets) as prev_in_octets by node interface\n| eval delta_time_sec = (_time - prev_time_ms)\n| eval delta_in_octets = in_octets - prev_in_octets\n| where delta_time_sec > 0 AND delta_in_octets > 0\n| eval in_bps = round((delta_in_octets*8)/delta_time_sec)\n| eval in_util_perc = round((in_bps/speed)*100, 2)\n| where in_util_perc > 80\n| stats latest(in_util_perc) by node interface\n| stats count",
				"queryParameters": {
					"earliest": "-60m@m",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "util_gt_80"
		},
		"ds_M8XEmGLx": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"if-stats.in_octets\") as in_octets latest(\"if-stats.speed\") as speed WHERE index=\"cisco_metrics\" node=* interface=* span=60s by node interface\n| streamstats current=f latest(_time) as prev_time_ms by node interface\n| streamstats current=f latest(in_octets) as prev_in_octets by node interface\n| eval delta_time_sec = (_time - prev_time_ms)\n| eval delta_in_octets = in_octets - prev_in_octets\n| where delta_time_sec > 0 AND delta_in_octets > 0\n| eval in_bps = round((delta_in_octets*8)/delta_time_sec)\n| eval in_util_perc = round((in_bps/speed)*100, 2)\n| where in_util_perc > 50\n| where in_util_perc <= 80\n| stats latest(in_util_perc) by node interface\n| stats count",
				"queryParameters": {
					"earliest": "-60m@m",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "util_gt_50_lt_80"
		},
		"ds_4g0DvUe2": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"if-stats.in_octets\") as in_octets latest(\"if-stats.speed\") as speed WHERE index=\"cisco_metrics\" node=* interface=* span=60s by node interface\n| streamstats current=f latest(_time) as prev_time_ms by node interface\n| streamstats current=f latest(in_octets) as prev_in_octets by node interface\n| eval delta_time_sec = (_time - prev_time_ms)\n| eval delta_in_octets = in_octets - prev_in_octets\n| where delta_time_sec > 0 AND delta_in_octets > 0\n| eval in_bps = round((delta_in_octets*8)/delta_time_sec)\n| eval in_util_perc = round((in_bps/speed)*100, 2)\n| where in_util_perc <= 50\n| stats latest(in_util_perc) by node interface\n| stats count",
				"queryParameters": {
					"earliest": "-60m@m",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "util_lt_50"
		}
	},
	"visualizations": {
		"viz_N8EKqJPv": {
			"type": "splunk.singlevalue",
			"options": {
				"numberPrecision": 0,
				"sparklineDisplay": "below",
				"trendDisplay": "absolute",
				"unitPosition": "after",
				"shouldUseThousandSeparators": true,
				"backgroundColor": "> majorValue | rangeValue(convertedColorRange)"
			},
			"context": {
				"convertedColorRange": [
					{
						"from": 0,
						"value": "#d41f1f"
					},
